// Theme-independent tokens.
export const shared = {
  'font-heading': "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif",
  'font-sans': "'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', system-ui, sans-serif",
  'font-mono': "ui-monospace, 'SF Mono', 'JetBrains Mono', Menlo, Consolas, monospace",
  'text-2xs': '11px',
  'text-xs': '12px',
  'text-sm': '14px',
  'text-md': '16px',
  'text-lg': '18px',
  'text-xl': '22px',
  'text-2xl': '28px',
  'text-3xl': '36px',
  'text-4xl': '48px',
  'leading-tight': '1.15',
  'leading-snug': '1.35',
  'leading-body': '1.6',
  'space-1': '4px',
  'space-2': '8px',
  'space-3': '12px',
  'space-4': '16px',
  'space-5': '24px',
  'space-6': '32px',
  'space-7': '40px',
  'space-8': '48px',
  'space-9': '64px',
  'radius-sm': '6px',
  'radius-md': '8px',
  'radius-lg': '12px',
  'radius-xl': '16px',
  'radius-pill': '999px',
  'ease-out': 'cubic-bezier(0.22, 1, 0.36, 1)',
  'ease-in-out': 'cubic-bezier(0.65, 0, 0.35, 1)',
  'dur-fast': '120ms',
  'dur-base': '200ms',
  'dur-slow': '360ms',
};

// Derived per theme from --shadow-color so both themes read as soft, cool elevation.
const shadows = (dark) => ({
  'shadow-sm': `0 1px 2px rgba(var(--shadow-color), ${dark ? 0.4 : 0.06})`,
  'shadow-md': `0 1px 2px rgba(var(--shadow-color), ${dark ? 0.4 : 0.05}), 0 8px 24px rgba(var(--shadow-color), ${dark ? 0.35 : 0.07})`,
  'shadow-lg': `0 2px 4px rgba(var(--shadow-color), ${dark ? 0.4 : 0.05}), 0 20px 48px rgba(var(--shadow-color), ${dark ? 0.45 : 0.1})`,
});

const decl = (obj, indent = '  ') => Object.entries(obj).map(([k, v]) => `${indent}--${k}: ${v};`).join('\n');

export function buildCss() {
  const L = { ...light, ...shadows(false) };
  const D = { ...dark, ...shadows(true) };
  return `/* GENERATED by design/build-tokens.mjs from design/tokens.mjs. Do not edit by hand. */

:root {
${decl(shared)}
${decl(L)}
  color-scheme: light;
}

:root.dark,
:root[data-theme='dark'] {
${decl(D)}
  color-scheme: dark;
}

/* No explicit choice (desktop app, first paint): follow the system. */
@media (prefers-color-scheme: dark) {
  :root:not(.light):not([data-theme='light']):not(.dark) {
${decl(D, '    ')}
    color-scheme: dark;
  }
}
`;
}
